 const choice=transition.choice===null?`<h3>Verein für die nächste Saison</h3><button type="button" data-v169-offer="stay">Bei ${v161Escape(club.name)} bleiben</button>${transition.offers.map(id=>{const c=v66Club(career,id);return`<button type="button" data-v169-offer="${id}">Zu ${v161Escape(c.name)} wechseln · ${c.balance} Credits · ${c.roster.length} Profis</button>`;}).join('')}`:`<p>${transition.choice==='stay'?'Du bleibst bei':'Neue Station:'} ${v161Escape(club.name)}.</p><button type="button" data-v169-action="next">Saison ${world.season+1} beginnen</button>`;
